import os, pty, subprocess, time, select, fcntl, termios, struct, signal

def run(args, inp, env=None, rows=24, cols=80, timeout=2):
    master, slave = pty.openpty()
    # set winsize on slave
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    e=os.environ.copy();
    if env: e.update(env)
    p=subprocess.Popen(['./executable']+args, stdin=slave, stdout=slave, stderr=slave, env=e, close_fds=True)
    os.close(slave)
    out=b''
    # write input after short delay
    time.sleep(0.1)
    if inp:
        os.write(master, inp)
    # send Ctrl-D EOF
    time.sleep(0.1)
    try: os.write(master, b'\x04')
    except OSError: pass
    deadline=time.time()+timeout
    while time.time()<deadline:
        r,_,_=select.select([master],[],[],0.05)
        if r:
            try:
                b=os.read(master, 4096)
            except OSError:
                break
            if not b: break
            out += b
        if p.poll() is not None:
            # drain
            while True:
                r,_,_=select.select([master],[],[],0)
                if not r: break
                try:
                    b=os.read(master,4096)
                except OSError: break
                if not b: break
                out+=b
            break
    if p.poll() is None:
        p.terminate();
        try: p.wait(0.5)
        except: p.kill()
    os.close(master)
    return p.returncode, out

