    master,slave=pty.openpty(); fcntl.ioctl(slave,termios.TIOCSWINSZ,struct.pack('HHHH',12,40,0,0))
    e=os.environ.copy();
    if env: e.update(env)
    def preexec(): os.setsid(); fcntl.ioctl(slave, termios.TIOCSCTTY, 0)
    stdin=subprocess.PIPE if inp is not None else slave
    p=subprocess.Popen(['./executable']+args, stdin=stdin, stdout=slave, stderr=slave, env=e, preexec_fn=preexec, close_fds=False)
    os.close(slave)
    if inp is not None:
        try:p.stdin.write(inp); p.stdin.close()
        except BrokenPipeError:pass
    out=b''; sent=False; deadline=time.time()+timeout
    while time.time()<deadline:
        r,_,_=select.select([master],[],[],0.05)
        if r:
            try:b=os.read(master,65536)
            except OSError:break
            if not b:break
            out+=b
            if (not sent) and b'\x1b_Gi=1' in out:
                if resp is not None: os.write(master, resp)
                sent=True
        if p.poll() is not None:break
    rc=p.poll()
    if rc is None:
        p.kill();
        try:p.wait(1)
        except:pass
        rc='killed'
    while True:
        r,_,_=select.select([master],[],[],0)
        if not r:break
        try:b=os.read(master,65536)
        except OSError:break
        if not b:break
        out+=b
    os.close(master);return rc,out,sent

