#!/usr/bin/env python3
import sys, os, json, time, base64, zlib, struct, shutil, select, termios, fcntl, re, urllib.request, urllib.parse

HELP = """Usage: jplot [OPTIONS] FIELD_SPEC [FIELD_SPEC...]:

OPTIONS:
  -interval duration
    \tWhen url is provided, defines the interval between fetches. Note that counter fields are computed based on this interval. (default 1s)
  -rows int
    \tLimits the height of the graph output.
  -steps int
    \tNumber of values to plot. (default 100)
  -url string
    \tURL to fetch every second. Read JSON objects from stdin if not specified.

FIELD_SPEC: [<option>[,<option>...]:]path
  option:
    - counter: Computes the difference with the last value. The value must increase monotonically.
    - marker: When the value is none-zero, a vertical line is drawn.
  path:
    JSON field path (eg: field.sub-field).
"""

class Config:
    def __init__(self):
        self.interval_s = 1.0
        self.interval_text = '1s'
        self.rows = 0
        self.steps = 100
        self.url = ''
        self.args = []

class TermInfo:
    def __init__(self):
        self.kind = None   # iterm, sixel, none
        self.probe = b''
        self.supported = False


def write_stdout_bytes(b):
    try:
        os.write(1, b)
    except OSError:
        pass

def print_usage():
    sys.stderr.write(HELP)

# ---------------- flag parser (Go flag-like subset) ----------------
def parse_int_flag(name, val):
    try:
        # Go's Atoi accepts a leading sign only, not spaces or floats.
        if not re.fullmatch(r'[+-]?\d+', val or ''):
            raise ValueError
        return int(val, 10)
    except Exception:
        raise ValueError(f'invalid value "{val}" for flag -{name}: parse error')

def parse_duration(val):
    # Sufficient facsimile of time.ParseDuration for CLI validation.
    if not val:
        raise ValueError(f'invalid value "{val}" for flag -interval: parse error')
    pat = re.compile(r'([+-]?(?:\d+(?:\.\d*)?|\.\d+))(ns|us|µs|μs|ms|s|m|h)')
    pos = 0; total = 0.0
    sign_allowed = True
    for m in pat.finditer(val):
        if m.start() != pos:
            raise ValueError(f'invalid value "{val}" for flag -interval: parse error')
        num = float(m.group(1)); unit = m.group(2)
        mult = {'ns':1e-9,'us':1e-6,'µs':1e-6,'μs':1e-6,'ms':1e-3,'s':1.0,'m':60.0,'h':3600.0}[unit]
        total += num * mult
        pos = m.end(); sign_allowed = False
    if pos != len(val) or pos == 0:
        raise ValueError(f'invalid value "{val}" for flag -interval: parse error')
    return total

def parse_flags(argv):
    cfg = Config()
    args = list(argv)
    i = 0
    positionals = []
    known = {'rows','steps','interval','url'}
    while i < len(args):
        a = args[i]
        if a == '--':
            positionals.extend(args[i+1:]); break
        if not a.startswith('-') or a == '-':
            positionals.extend(args[i:]); break
        # strip one or two leading dashes, like Go flag package display.
        nameval = a[2:] if a.startswith('--') else a[1:]
        if nameval in ('h','help'):
            raise RuntimeError('HELP')
        if '=' in nameval:
            name, val = nameval.split('=',1)
            has_val = True
        else:
            name = nameval; val = None; has_val = False
        if name not in known:
            raise ValueError(f'flag provided but not defined: -{name}')
        if not has_val:
            if i+1 >= len(args):
                raise ValueError(f'flag needs an argument: -{name}')
            val = args[i+1]
            i += 1
        if name == 'rows': cfg.rows = parse_int_flag(name, val)
        elif name == 'steps': cfg.steps = parse_int_flag(name, val)
        elif name == 'interval':
            cfg.interval_s = parse_duration(val); cfg.interval_text = val
        elif name == 'url': cfg.url = val
        i += 1
    cfg.args = positionals
    return cfg

# ---------------- terminal detection ----------------
def read_tty_response(pattern=None, timeout=0.15):
    # Try controlling tty first, then stdin if it is a tty. This intentionally
    # uses normal terminal I/O, not tracing/instrumentation.
    fds_to_try = []
    try:
        fd = os.open('/dev/tty', os.O_RDWR | os.O_NOCTTY | os.O_NONBLOCK)
        fds_to_try.append((fd, True))
    except OSError:
        pass
    if os.isatty(0):
        try:
            os.set_blocking(0, False)
        except Exception:
            pass
        fds_to_try.append((0, False))
    data = b''
    end = time.time() + timeout
    for fd, closeit in fds_to_try:
        while time.time() < end:
            r,_,_ = select.select([fd], [], [], max(0, min(0.02, end-time.time())))
            if not r: continue
            try:
                chunk = os.read(fd, 4096)
            except OSError:
                break
            if not chunk: break
            data += chunk
            if (pattern is None and data) or (pattern and pattern in data):
                if closeit: os.close(fd)
                return data
        if closeit:
            try: os.close(fd)
            except OSError: pass
    return data

def init_terminal():
    ti = TermInfo()
    if os.environ.get('TERM_PROGRAM') == 'iTerm.app':
        ti.kind = 'iterm'; ti.supported = True
        return ti
    if os.isatty(1):
        # Observed order on a terminal: Kitty graphics query, then DA query.
        q = b'\x1b_Gi=1,a=q,t=d,f=24\x1b\\'
        write_stdout_bytes(q); ti.probe += q
        read_tty_response(timeout=0.05)
        q = b'\x1b[c'
        write_stdout_bytes(q); ti.probe += q
        resp = read_tty_response(timeout=0.20)
        # DEC private DA parameter 4 advertises sixel on xterm-family terms.
        if b';4' in resp or b'?4' in resp or re.search(br'\[\?[0-9;]*4[0-9;]*c', resp):
            ti.kind = 'sixel'; ti.supported = True
        else:
            # Be permissive for TERM names; the original still probes, but this
            # makes the reimplementation useful under common sixel terminals.
            term = os.environ.get('TERM','').lower()
            if 'sixel' in term:
                ti.kind = 'sixel'; ti.supported = True
            else:
                ti.kind = None; ti.supported = False
        return ti
    else:
        q = b'\x1b[c'
        write_stdout_bytes(q); ti.probe += q
        ti.kind = None; ti.supported = False
        return ti

# ---------------- field specs and data extraction ----------------
class Field:
    def __init__(self, path, counter=False, marker=False):
        self.path = path
        self.counter = counter
        self.marker = marker
        self.last = None

def parse_specs(args):
    graphs = []
    for arg in args:
        fields = []
        for part in arg.split('+'):
            opts = []
            path = part
            if ':' in part:
                left, path = part.split(':', 1)
                opts = left.split(',')
            counter = marker = False
            for opt in opts:
                if opt == 'counter': counter = True
                elif opt == 'marker': marker = True
                else: raise ValueError(f'invalid field option: {opt}')
            fields.append(Field(path, counter, marker))
        graphs.append(fields)
    return graphs

def go_type(v):
    if v is None: return '<nil>'
    if isinstance(v, bool): return 'bool'
    if isinstance(v, str): return 'string'
    if isinstance(v, dict): return 'map[string]interface {}'
    if isinstance(v, list): return '[]interface {}'
    return type(v).__name__

def get_path(obj, path):
    cur = obj
    for piece in path.split('.'):
        if not isinstance(cur, dict):
            raise KeyError(f'{piece} is not an object. map[]')
        if piece not in cur:
            raise KeyError(f'{piece} does not exist.')
        cur = cur[piece]
    if not isinstance(cur, (int, float)) or isinstance(cur, bool):
        raise TypeError(f'invalid type {path}: {go_type(cur)}')
    return float(cur)

def json_error_message(line, exc):
    s = line.lstrip()
    if s.startswith('n') and not s.startswith('null'):
        return "invalid character 'o' in literal null (expecting 'u')"
    if '}{' in line:
        return "invalid character '{' after top-level value"
    # A few Go-like common cases.
    if s.startswith('t') and not s.startswith('true'):
        return "invalid character %r in literal true (expecting 'r')" % (s[1:2] or '')
    if s.startswith('f') and not s.startswith('false'):
        return "invalid character %r in literal false (expecting 'a')" % (s[1:2] or '')
    return str(exc)

def process_object(obj, graphs):
    sample = []
    for fields in graphs:
        vals = []
        for f in fields:
            try:
                val = get_path(obj, f.path)
            except KeyError as e:
                msg = e.args[0]
                raise RuntimeError(f'cannot get {f.path}: {msg}')
            except TypeError as e:
                raise RuntimeError(str(e))
            if f.counter:
                if f.last is None:
                    out = 0.0
                else:
                    out = val - f.last
                    if out < 0:
                        out = 0.0
                f.last = val
                val = out
            vals.append((val, f.marker))
        sample.append(vals)
    return sample

def read_stdin_samples(graphs):
    samples = []
    data = sys.stdin.read()
    if data == '':
        return samples
    # The original stdin source is line-oriented JSON.
    lines = data.splitlines()
    if not lines and data:
        lines=[data]
    for line in lines:
        if line == '':
            continue
        try:
            obj = json.loads(line)
        except Exception as e:
            raise RuntimeError('input error: ' + json_error_message(line, e))
