def fetch_url_sample(url, graphs):
    parsed = urllib.parse.urlparse(url)
    if not parsed.scheme:
        raise RuntimeError(f'input error: parse "{url}": missing protocol scheme')
    try:
        with urllib.request.urlopen(url, timeout=5) as r:
            body = r.read().decode('utf-8', 'replace')
    except urllib.error.HTTPError as e:
        # Observed behavior accepts the response body regardless of status.
        body = e.read().decode('utf-8','replace')
    except Exception as e:
        raise RuntimeError('input error: ' + str(e))
    try:
        obj = json.loads(body)
    except Exception as e:
        raise RuntimeError('input error: ' + json_error_message(body, e))
    return [process_object(obj, graphs)]

# ---------------- simple image encoders/renderers ----------------
def png_bytes(width, height, graphs, history):
    width = max(1, int(width)); height = max(1, int(height))
    # RGB image with black background, light grid, colored traces.
    img = bytearray([0,0,0] * width * height)
    def pix(x,y,c):
        if 0 <= x < width and 0 <= y < height:
            idx=(y*width+x)*3; img[idx:idx+3]=bytes(c)
    # grid
    for y in range(0,height,max(1,height//4)):
        for x in range(width): pix(x,y,(22,22,22))
    for x in range(0,width,max(1,width//10)):
        for y in range(height): pix(x,y,(16,16,16))
    colors=[(31,119,180),(255,127,14),(44,160,44),(214,39,40),(148,103,189),(140,86,75)]
    if history:
        graph_count = max(1, len(graphs))
        gh = max(1, height // graph_count)
        steps = max(1, len(history))
        for gi in range(graph_count):
            y0 = gi*gh; y1 = height-1 if gi == graph_count-1 else (gi+1)*gh-1
            vals_by_field=[]
            maxv=0.0
            for sample in history:
                if gi < len(sample):
                    for fi,(v,m) in enumerate(sample[gi]):
                        while len(vals_by_field)<=fi: vals_by_field.append([])
                        vals_by_field[fi].append(v)
                        maxv=max(maxv, abs(v))
            if maxv == 0: maxv = 1.0
            # border
            for x in range(width): pix(x,y0,(55,55,55)); pix(x,y1,(55,55,55))
            for fi,vals in enumerate(vals_by_field):
                col=colors[fi % len(colors)]
                prev=None
                for i,v in enumerate(vals[-width:]):
                    x = int(i * (width-1) / max(1, min(width,len(vals))-1)) if min(width,len(vals))>1 else width-1
                    frac = max(0.0, min(1.0, v/maxv))
                    y = y1 - int(frac * max(0, y1-y0-1))
                    pix(x,y,col)
                    if prev:
                        px,py=prev
                        # simple line interpolation
                        n=max(abs(x-px),abs(y-py),1)
                        for k in range(n+1):
                            xx=px+(x-px)*k//n; yy=py+(y-py)*k//n; pix(xx,yy,col)
                    prev=(x,y)
