    cfg = Config()
    args = list(argv)
    i = 0
    positionals = []
    known = {'rows','steps','interval','url'}
    while i < len(args):
        a = args[i]
        if a == '--':
            positionals.extend(args[i+1:]); break
        if not a.startswith('-') or a == '-':
            positionals.extend(args[i:]); break
        # strip one or two leading dashes, like Go flag package display.
        nameval = a[2:] if a.startswith('--') else a[1:]
        if nameval in ('h','help'):
            raise RuntimeError('HELP')
        if '=' in nameval:
            name, val = nameval.split('=',1)
            has_val = True
        else:
            name = nameval; val = None; has_val = False
        if name not in known:
            raise ValueError(f'flag provided but not defined: -{name}')
        if not has_val:
            if i+1 >= len(args):
                raise ValueError(f'flag needs an argument: -{name}')
            val = args[i+1]
            i += 1
        if name == 'rows': cfg.rows = parse_int_flag(name, val)
        elif name == 'steps': cfg.steps = parse_int_flag(name, val)
