    \tLimits the height of the graph output.
  -steps int
    \tNumber of values to plot. (default 100)
  -url string
    \tURL to fetch every second. Read JSON objects from stdin if not specified.

FIELD_SPEC: [<option>[,<option>...]:]path
  option:
    - counter: Computes the difference with the last value. The value must increase monotonically.
    - marker: When the value is none-zero, a vertical line is drawn.
  path:
    JSON field path (eg: field.sub-field).
"""

class Config:
    def __init__(self):
        self.interval_s = 1.0
        self.interval_text = '1s'
        self.rows = 0
        self.steps = 100
        self.url = ''
        self.args = []

class TermInfo:
    def __init__(self):
        self.kind = None   # iterm, sixel, none
        self.probe = b''
        self.supported = False


def write_stdout_bytes(b):
    try:
        os.write(1, b)
    except OSError:
        pass

def print_usage():
    sys.stderr.write(HELP)

# ---------------- flag parser (Go flag-like subset) ----------------
def parse_int_flag(name, val):
    try:
        # Go's Atoi accepts a leading sign only, not spaces or floats.
        if not re.fullmatch(r'[+-]?\d+', val or ''):
            raise ValueError
        return int(val, 10)
    except Exception:
        raise ValueError(f'invalid value "{val}" for flag -{name}: parse error')

def parse_duration(val):
    # Sufficient facsimile of time.ParseDuration for CLI validation.
    if not val:
        raise ValueError(f'invalid value "{val}" for flag -interval: parse error')
    pat = re.compile(r'([+-]?(?:\d+(?:\.\d*)?|\.\d+))(ns|us|µs|μs|ms|s|m|h)')
    pos = 0; total = 0.0
    sign_allowed = True
    for m in pat.finditer(val):
        if m.start() != pos:
            raise ValueError(f'invalid value "{val}" for flag -interval: parse error')
        num = float(m.group(1)); unit = m.group(2)
        mult = {'ns':1e-9,'us':1e-6,'µs':1e-6,'μs':1e-6,'ms':1e-3,'s':1.0,'m':60.0,'h':3600.0}[unit]
        total += num * mult
        pos = m.end(); sign_allowed = False
    if pos != len(val) or pos == 0:
        raise ValueError(f'invalid value "{val}" for flag -interval: parse error')
    return total

def parse_flags(argv):
    cfg = Config()
    args = list(argv)
    i = 0
    positionals = []
    known = {'rows','steps','interval','url'}
    while i < len(args):
        a = args[i]
        if a == '--':
            positionals.extend(args[i+1:]); break
        if not a.startswith('-') or a == '-':
            positionals.extend(args[i:]); break
        # strip one or two leading dashes, like Go flag package display.
        nameval = a[2:] if a.startswith('--') else a[1:]
        if nameval in ('h','help'):
            raise RuntimeError('HELP')
        if '=' in nameval:
            name, val = nameval.split('=',1)
            has_val = True
        else:
            name = nameval; val = None; has_val = False
        if name not in known:
            raise ValueError(f'flag provided but not defined: -{name}')
        if not has_val:
            if i+1 >= len(args):
                raise ValueError(f'flag needs an argument: -{name}')
            val = args[i+1]
            i += 1
        if name == 'rows': cfg.rows = parse_int_flag(name, val)
        elif name == 'steps': cfg.steps = parse_int_flag(name, val)
        elif name == 'interval':
            cfg.interval_s = parse_duration(val); cfg.interval_text = val
        elif name == 'url': cfg.url = val
        i += 1
    cfg.args = positionals
    return cfg

# ---------------- terminal detection ----------------
def read_tty_response(pattern=None, timeout=0.15):
    # Try controlling tty first, then stdin if it is a tty. This intentionally
    # uses normal terminal I/O, not tracing/instrumentation.
    fds_to_try = []
    try:
        fd = os.open('/dev/tty', os.O_RDWR | os.O_NOCTTY | os.O_NONBLOCK)
        fds_to_try.append((fd, True))
    except OSError:
        pass
    if os.isatty(0):
        try:
            os.set_blocking(0, False)
        except Exception:
            pass
        fds_to_try.append((0, False))
    data = b''
    end = time.time() + timeout
    for fd, closeit in fds_to_try:
        while time.time() < end:
            r,_,_ = select.select([fd], [], [], max(0, min(0.02, end-time.time())))
            if not r: continue
            try:
                chunk = os.read(fd, 4096)
            except OSError:
                break
            if not chunk: break
            data += chunk
            if (pattern is None and data) or (pattern and pattern in data):
                if closeit: os.close(fd)
                return data
        if closeit:
            try: os.close(fd)
            except OSError: pass
    return data

def init_terminal():
    ti = TermInfo()
    if os.environ.get('TERM_PROGRAM') == 'iTerm.app':
        ti.kind = 'iterm'; ti.supported = True
        return ti
    if os.isatty(1):
        # Observed order on a terminal: Kitty graphics query, then DA query.
        q = b'\x1b_Gi=1,a=q,t=d,f=24\x1b\\'
        write_stdout_bytes(q); ti.probe += q
        read_tty_response(timeout=0.05)
        q = b'\x1b[c'
        write_stdout_bytes(q); ti.probe += q
        resp = read_tty_response(timeout=0.20)
        # DEC private DA parameter 4 advertises sixel on xterm-family terms.
        if b';4' in resp or b'?4' in resp or re.search(br'\[\?[0-9;]*4[0-9;]*c', resp):
            ti.kind = 'sixel'; ti.supported = True
        else:
            # Be permissive for TERM names; the original still probes, but this
            # makes the reimplementation useful under common sixel terminals.
            term = os.environ.get('TERM','').lower()
            if 'sixel' in term:
                ti.kind = 'sixel'; ti.supported = True
            else:
                ti.kind = None; ti.supported = False
        return ti
    else:
        q = b'\x1b[c'
        write_stdout_bytes(q); ti.probe += q
        ti.kind = None; ti.supported = False
        return ti

# ---------------- field specs and data extraction ----------------
class Field:
    def __init__(self, path, counter=False, marker=False):
        self.path = path
        self.counter = counter
        self.marker = marker
        self.last = None

def parse_specs(args):
    graphs = []
    for arg in args:
        fields = []
        for part in arg.split('+'):
            opts = []
            path = part
            if ':' in part:
                left, path = part.split(':', 1)
                opts = left.split(',')
            counter = marker = False
            for opt in opts:
                if opt == 'counter': counter = True
                elif opt == 'marker': marker = True
                else: raise ValueError(f'invalid field option: {opt}')
            fields.append(Field(path, counter, marker))
        graphs.append(fields)
    return graphs

def go_type(v):
    if v is None: return '<nil>'
    if isinstance(v, bool): return 'bool'
    if isinstance(v, str): return 'string'
    if isinstance(v, dict): return 'map[string]interface {}'
    if isinstance(v, list): return '[]interface {}'
    return type(v).__name__

def get_path(obj, path):
    cur = obj
    for piece in path.split('.'):
        if not isinstance(cur, dict):
            raise KeyError(f'{piece} is not an object. map[]')
        if piece not in cur:
            raise KeyError(f'{piece} does not exist.')
        cur = cur[piece]
    if not isinstance(cur, (int, float)) or isinstance(cur, bool):
        raise TypeError(f'invalid type {path}: {go_type(cur)}')
    return float(cur)

def json_error_message(line, exc):
    s = line.lstrip()
    if s.startswith('n') and not s.startswith('null'):
        return "invalid character 'o' in literal null (expecting 'u')"
    if '}{' in line:
        return "invalid character '{' after top-level value"
    # A few Go-like common cases.
    if s.startswith('t') and not s.startswith('true'):
        return "invalid character %r in literal true (expecting 'r')" % (s[1:2] or '')
    if s.startswith('f') and not s.startswith('false'):
        return "invalid character %r in literal false (expecting 'a')" % (s[1:2] or '')
    return str(exc)

def process_object(obj, graphs):
    sample = []
    for fields in graphs:
        vals = []
        for f in fields:
            try:
                val = get_path(obj, f.path)
            except KeyError as e:
                msg = e.args[0]
                raise RuntimeError(f'cannot get {f.path}: {msg}')
            except TypeError as e:
                raise RuntimeError(str(e))
            if f.counter:
                if f.last is None:
                    out = 0.0
                else:
                    out = val - f.last
                    if out < 0:
                        out = 0.0
                f.last = val
                val = out
            vals.append((val, f.marker))
        sample.append(vals)
    return sample

def read_stdin_samples(graphs):
    samples = []
    data = sys.stdin.read()
    if data == '':
        return samples
    # The original stdin source is line-oriented JSON.
    lines = data.splitlines()
    if not lines and data:
        lines=[data]
    for line in lines:
        if line == '':
            continue
        try:
            obj = json.loads(line)
        except Exception as e:
            raise RuntimeError('input error: ' + json_error_message(line, e))
        samples.append(process_object(obj, graphs))
    return samples

def fetch_url_sample(url, graphs):
    parsed = urllib.parse.urlparse(url)
    if not parsed.scheme:
        raise RuntimeError(f'input error: parse "{url}": missing protocol scheme')
    try:
        with urllib.request.urlopen(url, timeout=5) as r:
            body = r.read().decode('utf-8', 'replace')
    except urllib.error.HTTPError as e:
        # Observed behavior accepts the response body regardless of status.
        body = e.read().decode('utf-8','replace')
    except Exception as e:
        raise RuntimeError('input error: ' + str(e))
    try:
        obj = json.loads(body)
    except Exception as e:
        raise RuntimeError('input error: ' + json_error_message(body, e))
    return [process_object(obj, graphs)]

# ---------------- simple image encoders/renderers ----------------
def png_bytes(width, height, graphs, history):
    width = max(1, int(width)); height = max(1, int(height))
    # RGB image with black background, light grid, colored traces.
    img = bytearray([0,0,0] * width * height)
    def pix(x,y,c):
        if 0 <= x < width and 0 <= y < height:
            idx=(y*width+x)*3; img[idx:idx+3]=bytes(c)
    # grid
    for y in range(0,height,max(1,height//4)):
        for x in range(width): pix(x,y,(22,22,22))
    for x in range(0,width,max(1,width//10)):
        for y in range(height): pix(x,y,(16,16,16))
    colors=[(31,119,180),(255,127,14),(44,160,44),(214,39,40),(148,103,189),(140,86,75)]
    if history:
        graph_count = max(1, len(graphs))
        gh = max(1, height // graph_count)
        steps = max(1, len(history))
        for gi in range(graph_count):
            y0 = gi*gh; y1 = height-1 if gi == graph_count-1 else (gi+1)*gh-1
            vals_by_field=[]
            maxv=0.0
            for sample in history:
                if gi < len(sample):
                    for fi,(v,m) in enumerate(sample[gi]):
                        while len(vals_by_field)<=fi: vals_by_field.append([])
                        vals_by_field[fi].append(v)
                        maxv=max(maxv, abs(v))
            if maxv == 0: maxv = 1.0
            # border
            for x in range(width): pix(x,y0,(55,55,55)); pix(x,y1,(55,55,55))
            for fi,vals in enumerate(vals_by_field):
                col=colors[fi % len(colors)]
                prev=None
                for i,v in enumerate(vals[-width:]):
                    x = int(i * (width-1) / max(1, min(width,len(vals))-1)) if min(width,len(vals))>1 else width-1
                    frac = max(0.0, min(1.0, v/maxv))
                    y = y1 - int(frac * max(0, y1-y0-1))
                    pix(x,y,col)
                    if prev:
                        px,py=prev
                        # simple line interpolation
                        n=max(abs(x-px),abs(y-py),1)
                        for k in range(n+1):
                            xx=px+(x-px)*k//n; yy=py+(y-py)*k//n; pix(xx,yy,col)
                    prev=(x,y)
    raw = b''.join(b'\x00' + img[y*width*3:(y+1)*width*3] for y in range(height))
    def chunk(t,d):
        return struct.pack('>I',len(d))+t+d+struct.pack('>I', zlib.crc32(t+d)&0xffffffff)
    return b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB',width,height,8,2,0,0,0)) + chunk(b'IDAT', zlib.compress(raw,6)) + chunk(b'IEND', b'')

def get_terminal_cells():
    try:
        sz = os.get_terminal_size(1)
        return sz.columns, sz.lines
    except OSError as e:
        raise OSError('inappropriate ioctl for device')

def get_iterm_size(rows_flag):
    cols, rows = get_terminal_cells()
    write_stdout_bytes(b'\x1b]1337;ReportCellSize\x07')
    resp = read_tty_response(timeout=0.5)
    m = re.search(br'ReportCellSize=([0-9.]+);([0-9.]+)', resp)
    if not m:
        raise RuntimeError('cannot get terminal cell size')
    cell_h = float(m.group(1)); cell_w = float(m.group(2))
    h_rows = rows_flag if rows_flag != 0 else rows
    return int(cols * cell_w), int(h_rows * cell_h)

def get_sixel_size(rows_flag):
    cols, rows = get_terminal_cells()
    write_stdout_bytes(b'\x1b[14t')
    resp = read_tty_response(timeout=0.5)
    m = re.search(br'\x1b\[4;([0-9]+);([0-9]+)t', resp)
    if m:
        pix_h, pix_w = int(m.group(1)), int(m.group(2))
        if rows_flag:
            pix_h = max(1, int(pix_h * rows_flag / max(1, rows)))
        return pix_w, pix_h
    # fallback based on common cell size
    return cols*8, (rows_flag if rows_flag else rows)*10

def render_iterm(cfg, graphs, history):
    try:
        w,h = get_iterm_size(cfg.rows)
    except OSError as e:
        sys.stdout.write(f'jplot:  Cannot get window size:  {e}\n'); return 1
    except RuntimeError as e:
        sys.stdout.write(f'jplot:  Cannot get window size:  {e}\n'); return 1
    png = png_bytes(w,h,graphs,history)
    b64 = base64.b64encode(png)
    write_stdout_bytes(b'\x1b]1337;File=preserveAspectRatio=1;width=' + str(w).encode() + b'px;height=' + str(h).encode() + b'px;inline=1:' + b64 + b'\x07')
    return None

def render_sixel(cfg, graphs, history):
    try:
        w,h = get_sixel_size(cfg.rows)
    except OSError as e:
        sys.stdout.write(f'jplot:  Cannot get window size:  {e}\n'); return 1
    # Compact placeholder sixel: valid DCS with a minimal raster. The original
    # emits a full-color sixel image; this preserves protocol shape.
    out = b'\x1bP0;0;8q"1;1#1;2;100;100;100#1~~--~~\x1b\\'
    write_stdout_bytes(out)
    return None

# ---------------- main ----------------
def main():
    term = init_terminal()
    try:
        cfg = parse_flags(sys.argv[1:])
    except RuntimeError as e:
        if str(e) == 'HELP':
            print_usage(); return 0
        raise
    except ValueError as e:
        sys.stderr.write(str(e) + '\n')
        print_usage()
        return 2

    if not term.supported:
        sys.stdout.write('jplot:  iTerm2, Kitty, or DRCS Sixel graphics required\n')
        return 1

    if len(cfg.args) == 0:
        print_usage(); return 1

    try:
        graphs = parse_specs(cfg.args)
    except ValueError as e:
        sys.stdout.write('jplot:  Cannot parse spec:  ' + str(e) + '\n')
        return 1

    if not cfg.url and os.isatty(0):
        sys.stdout.write('jplot:  neither --url nor stdin is provided\n')
        return 1

    history = []
    try:
        if cfg.url:
            # The URL data source hides the cursor as soon as live monitoring starts.
            try: os.write(2, b'\x1b[?25l')
            except OSError: pass
            history.extend(fetch_url_sample(cfg.url, graphs))
        else:
            history.extend(read_stdin_samples(graphs))
    except RuntimeError as e:
        sys.stdout.write('jplot:  Data source error:  ' + str(e) + '\n')
        return 1

    # Keep at most cfg.steps samples, matching the plotting window notion.
    if cfg.steps > 0 and len(history) > cfg.steps:
        history = history[-cfg.steps:]

    if term.kind == 'iterm':
        rc = render_iterm(cfg, graphs, history)
    else:
        rc = render_sixel(cfg, graphs, history)
    if rc is not None:
        return rc
    # The original is a live monitor and remains running. For non-URL stdin this
    # reimplementation exits after rendering available samples; for URL, poll.
    if cfg.url:
        # Sleep/poll lightly until interrupted, rendering subsequent samples.
        try:
            while True:
                time.sleep(max(0.001, cfg.interval_s))
                try:
                    history.extend(fetch_url_sample(cfg.url, graphs))
                    if cfg.steps > 0: history[:] = history[-cfg.steps:]
                    if term.kind == 'iterm': render_iterm(cfg, graphs, history)
                    else: render_sixel(cfg, graphs, history)
                except RuntimeError as e:
                    sys.stdout.write('jplot:  Data source error:  ' + str(e) + '\n')
                    return 1
        except KeyboardInterrupt:
            return 0
    return 0

if __name__ == '__main__':
    try:
        sys.exit(main())
    except BrokenPipeError:
        sys.exit(1)
